# Compounds test data extracted from VAL by running:
#
# WITH "MATCH (sc:StudyCompound)-[rel_sc_cav:HAS_SELECTED_COMPOUND]->(cav:CompoundAliasValue)-[rel_cav_car:LATEST]-(car:CompoundAliasRoot)
#       WITH sc, cav, car, rel_sc_cav, rel_cav_car
#       MATCH (cav)-[rel_cav_cr:IS_COMPOUND]-(cr:CompoundRoot)-[rel_cr_cv:LATEST]-(cv:CompoundValue)
#       WITH *
#       MATCH (sc)-[rel_sc_roa:HAS_ROUTE_OF_ADMINISTRATION]-(ctt:CTTermRoot)
#       WITH *
#       MATCH (sc)-[rel_sc_scd:STUDY_COMPOUND_HAS_COMPOUND_DOSING]-(scd:StudyCompoundDosing)
#       WITH *
#       MATCH (scd)-[rel_scd_dv:HAS_DOSE_VALUE]-(nvr:NumericValueWithUnitRoot)
