TEST_DATA_COMPOUNDS = """

UNWIND [{_id:871865, properties:{uid:"StudyCompoundDosing_000001", order:1}}, {_id:892196, properties:{uid:"StudyCompoundDosing_000002", order:2}}, {_id:892200, properties:{uid:"StudyCompoundDosing_000002", order:2}}] AS row
MERGE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:StudyCompoundDosing:StudySelection;
UNWIND [{_id:864877, properties:{name:"Metformin", name_sentence_case:"metformin", is_preferred_synonym:true}}] AS row
MERGE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:ConceptValue:CompoundAliasValue;
UNWIND [{uid:"CompoundAlias_000003", properties:{}}] AS row
MERGE (n:ConceptRoot{uid: row.uid}) SET n += row.properties SET n:CompoundAliasRoot;
UNWIND [{uid:"C38288_ORAL", properties:{concept_id:"C38288"}}] AS row
MERGE (n:CTTermRoot{uid: row.uid}) SET n += row.properties;
UNWIND [{uid:"NumericValueWithUnit_000022", properties:{}}] AS row
MERGE (n:NumericValueRoot{uid: row.uid}) SET n += row.properties SET n:ConceptRoot:NumericValueWithUnitRoot:SimpleConceptRoot;
UNWIND [{_id:871456, properties:{uid:"StudyCompound_000007", order:2}}] AS row
MERGE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:StudyCompound:StudySelection;
UNWIND [{_id:864875, properties:{is_name_inn:true, is_sponsor_compound:false, name:"Metformin", name_sentence_case:"metformin"}}] AS row
MERGE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:ConceptValue:CompoundValue:TemplateParameterTermValue;
UNWIND [{uid:"Compound_000003", properties:{}}] AS row
MERGE (n:ConceptRoot{uid: row.uid}) SET n += row.properties SET n:TemplateParameterTermRoot:CompoundRoot;
UNWIND [{start: {_id:871456}, end: {_id:864877}, properties:{}}] AS row
MATCH (start:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.start._id})
MATCH (end:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.end._id})
MERGE (start)-[r:HAS_SELECTED_COMPOUND]->(end) SET r += row.properties;
UNWIND [{start: {uid:"Compound_000003"}, end: {_id:864875}, properties:{}}] AS row
MATCH (start:ConceptRoot{uid: row.start.uid})
MATCH (end:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.end._id})
MERGE (start)-[r:LATEST]->(end) SET r += row.properties;
UNWIND [{start: {_id:871456}, end: {uid:"C38288_ORAL"}, properties:{}}] AS row
MATCH (start:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.start._id})
MATCH (end:CTTermRoot{uid: row.end.uid})
MERGE (start)-[r:HAS_ROUTE_OF_ADMINISTRATION]->(end) SET r += row.properties;
UNWIND [{start: {_id:871865}, end: {uid:"NumericValueWithUnit_000022"}, properties:{}}, {start: {_id:892196}, end: {uid:"NumericValueWithUnit_000022"}, properties:{}}, {start: {_id:892200}, end: {uid:"NumericValueWithUnit_000022"}, properties:{}}] AS row
MATCH (start:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.start._id})
MATCH (end:NumericValueRoot{uid: row.end.uid})
MERGE (start)-[r:HAS_DOSE_VALUE]->(end) SET r += row.properties;
UNWIND [{start: {_id:871456}, end: {_id:871865}, properties:{}}, {start: {_id:871456}, end: {_id:892196}, properties:{}}, {start: {_id:871456}, end: {_id:892200}, properties:{}}] AS row
MATCH (start:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.start._id})
MATCH (end:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.end._id})
MERGE (start)-[r:STUDY_COMPOUND_HAS_COMPOUND_DOSING]->(end) SET r += row.properties;
UNWIND [{start: {_id:864877}, end: {uid:"Compound_000003"}, properties:{}}] AS row
MATCH (start:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.start._id})
MATCH (end:ConceptRoot{uid: row.end.uid})
MERGE (start)-[r:IS_COMPOUND]->(end) SET r += row.properties;
UNWIND [{start: {uid:"CompoundAlias_000003"}, end: {_id:864877}, properties:{}}] AS row
MATCH (start:ConceptRoot{uid: row.start.uid})
MATCH (end:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.end._id})
MERGE (start)-[r:LATEST]->(end) SET r += row.properties;
MATCH (n:`UNIQUE IMPORT LABEL`)  WITH n LIMIT 20000 REMOVE n:`UNIQUE IMPORT LABEL` REMOVE n.`UNIQUE IMPORT ID`;

"""


